"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[9210],{9949:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>o,default:()=>m,frontMatter:()=>r,metadata:()=>s,toc:()=>d});var a=n(31085),h=n(71184);const r={sidebar_position:10,slug:"/bible/1_Machabees/1_Machabees_10",title:"1 Machabees 10",hide_table_of_contents:!0},o="1 Machabees",s={id:"bible/1 Machabees/1 Machabees 10",title:"1 Machabees 10",description:"Chapter 10",source:"@site/docs/bible/1 Machabees/1 Machabees 10.md",sourceDirName:"bible/1 Machabees",slug:"/bible/1_Machabees/1_Machabees_10",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_10",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Machabees/1 Machabees 10.md",tags:[],version:"current",sidebarPosition:10,frontMatter:{sidebar_position:10,slug:"/bible/1_Machabees/1_Machabees_10",title:"1 Machabees 10",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Machabees 9",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_9"},next:{title:"1 Machabees 11",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_11"}},i={},d=[{value:"Chapter 10",id:"chapter-10",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"1-machabees",children:"1 Machabees"}),"\n",(0,a.jsx)(t.h2,{id:"chapter-10",children:"Chapter 10"}),"\n",(0,a.jsx)(t.p,{children:"Alexander Bales sets himself up for king:  both he and Demetrius seek to make Jonathan their friend.  Alexander kills Demetrius in battle, and honours Jonathan.  His victory over Apollonius."}),"\n",(0,a.jsx)(n,{verse:1,children:"Now in the hundred and sixtieth year, Alexander, the son of Antiochus, surnamed the Illustrious, came up and took Ptolemais, and they received him, and he reigned there."}),"\n",(0,a.jsx)(n,{verse:2,children:"And king Demetrius heard of it, and gathered together an exceeding great army, and went forth against him to fight."}),"\n",(0,a.jsx)(n,{verse:3,children:"And Demetrius sent a letter to Jonathan, with peaceable words, to magnify him."}),"\n",(0,a.jsx)(n,{verse:4,children:"For he said: Let us first make a peace with him, before he make one with Alexander against us."}),"\n",(0,a.jsx)(n,{verse:5,children:"For he will remember all the evils that we have done against him, and against his brother, and against his nation."}),"\n",(0,a.jsx)(n,{verse:6,children:"And he gave him authority to gather together a army, and to make arms, and that he should be his confederate: and the hostages that were in the castle, he commanded to be delivered to him."}),"\n",(0,a.jsx)(n,{verse:7,children:"And Jonathan came to Jerusalem, and read the letters in the hearing of all the people, and of them that were in the castle."}),"\n",(0,a.jsx)(n,{verse:8,children:"And they were struck with great fear, because they heard that the king had given him authority to gather together an army."}),"\n",(0,a.jsx)(n,{verse:9,children:"And the hostages were delivered to Jonathan, and he restored them to their parents."}),"\n",(0,a.jsx)(n,{verse:10,children:"And Jonathan dwelt in Jerusalem, and began to build, and to repair the city."}),"\n",(0,a.jsx)(n,{verse:11,children:"And he ordered workmen to build the walls, and mount Sion round about with square stones for fortification: and so they did."}),"\n",(0,a.jsx)(n,{verse:12,children:"Then the strangers that were in the strong holds, which Bacchides had built, fled away."}),"\n",(0,a.jsx)(n,{verse:13,children:"And every man left his place, and departed into his own country:"}),"\n",(0,a.jsx)(n,{verse:14,children:"Only in Bethsura there remained some of them, that had forsaken the law, and the commandments of God: for this was a place of refuge for them."}),"\n",(0,a.jsx)(n,{verse:15,children:"And king Alexander heard of the promises that Demetrius had made Jonathan: and they told him of the battles, and the worthy acts that he and his brethren had done, and the labours that they had endured."}),"\n",(0,a.jsx)(n,{verse:16,children:"And he said: Shall we find such another man? now, therefore, we will make him our friend and our confederate."}),"\n",(0,a.jsx)(n,{verse:17,children:"So he wrote a letter, and sent it to him according to these words, saying:"}),"\n",(0,a.jsx)(n,{verse:18,children:"King Alexander to his brother, Jonathan, greetings."}),"\n",(0,a.jsx)(n,{verse:19,children:"We have heard of thee, that thou art a man of great power, and fit to be our friend:"}),"\n",(0,a.jsx)(n,{verse:20,children:"Now therefore, we make thee this day high priest of thy nation, and that thou be called the king's friend, (and he sent him a purple robe, and a crown of gold) and that thou be of one mind with us in our affairs, and keep friendship with us."}),"\n",(0,a.jsx)(n,{verse:21,children:"Then Jonathan put on the holy vestment in the seventh month, in the year one hundred and threescore, at the feast day of the tabernacles: and he gathered together an army, and made a great number of arms."}),"\n",(0,a.jsx)(n,{verse:22,children:"And Demetrius heard these words, and was exceeding sorry, and said:"}),"\n",(0,a.jsx)(n,{verse:23,children:"What is this that we have done, that Alexander hath prevented us to gain the friendship of the Jews to strengthen himself?"}),"\n",(0,a.jsx)(n,{verse:24,children:"I also will write to them words of request, and offer dignities, and gifts: that they may be with me to aid me."}),"\n",(0,a.jsx)(n,{verse:25,children:"And he wrote to them in these words: King Demetrius to the nation of the Jews, greeting."}),"\n",(0,a.jsx)(n,{verse:26,children:"Whereas you have kept covenant with us, and have continued in our friendship, and have not joined with our enemies, we have heard of it, and are glad."}),"\n",(0,a.jsx)(n,{verse:27,children:"Wherefore now continue still to keep fidelity towards us, and we will reward you with good things, for what you have done in our behalf."}),"\n",(0,a.jsx)(n,{verse:28,children:"And we will remit to you many charges, and will give you gifts."}),"\n",(0,a.jsx)(n,{verse:29,children:"And now I free you, and all the Jews, from tributes, and I release you from the customs of salt, and remit the crowns, and the thirds of the seed:"}),"\n",(0,a.jsx)(n,{verse:30,children:"And the half of the fruit of trees, which is my share, I leave to you from this day forward, so that it shall not be taken of the land of Juda, and of the three cities that are added thereto out of Samaria and Galilee, from this day forth, and for ever:"}),"\n",(0,a.jsx)(n,{verse:31,children:"And let Jerusalem be holy and free, with the borders thereof: and let the tenths, and tributes be for itself."}),"\n",(0,a.jsx)(n,{verse:32,children:"I yield up also the power of the castle that is in Jerusalem, and I give it to the high priest, to place therein such men as he shall choose, to keep it."}),"\n",(0,a.jsx)(n,{verse:33,children:"And every soul of the Jews that hath been carried captive from the land of Juda in all my kingdom, I set at liberty freely, that all be discharged from tributes, even of their cattle."}),"\n",(0,a.jsx)(n,{verse:34,children:"And I will that all the feasts, and the sabbaths, and the new moons, and the days appointed, and three days before the solemn day, and three days after the solemn day, be all days of immunity and freedom, for all the Jews that are in my kingdom:"}),"\n",(0,a.jsx)(n,{verse:35,children:"And no man shall have power to do any thing against them, or to molest any of them, in any cause."}),"\n",(0,a.jsx)(n,{verse:36,children:"And let there be enrolled in the king's army to the number of thirty thousand of the Jews: and allowance shall be made them, as is due to all the king's forces and certain of them shall be appointed to be in the fortresses of the great king:"}),"\n",(0,a.jsx)(n,{verse:37,children:"And some of them shall be set over the affairs of the kingdom, that are of trust, and let the governors be taken from among themselves, and let them walk in their own laws, as the king hath commanded in the land of Juda."}),"\n",(0,a.jsx)(n,{verse:38,children:"And the three cities that are added to Judea, out of the country of Samaria, let them be accounted with Judea: that they may be under one, and obey no other authority but that of the high priest:"}),"\n",(0,a.jsx)(n,{verse:39,children:"Ptolemais and the confines thereof, I give as a free gift to the holy places that are in Jerusalem, for the necessary charges of the holy things."}),"\n",(0,a.jsx)(n,{verse:40,children:"And I give every year fifteen thousand sickles of silver out of the king's accounts, of what belongs to me:"}),"\n",(0,a.jsx)(n,{verse:41,children:"And all that is above, which they that were over the affairs the years before, had not paid, from this time they shall give it to the works of the house."}),"\n",(0,a.jsx)(n,{verse:42,children:"Moreover, the five thousand sickles of silver, which they received from the account of the holy places, every year, shall also belong to the priests that execute the ministry."}),"\n",(0,a.jsx)(n,{verse:43,children:"And whosoever shall flee into the temple that is in Jerusalem, and in all the borders thereof, being indebted to the king for any matter, let them be set at liberty, and all that they have in my kingdom, let them have it free."}),"\n",(0,a.jsx)(n,{verse:44,children:"For the building also, or repairing the works of the holy places, the charges shall be given out of the king's revenues:"}),"\n",(0,a.jsx)(n,{verse:45,children:"For the building also of the walls of Jerusalem, and the fortifying thereof round about, the charges shall be given out of the king's account, as also for the building of the walls in Judea."}),"\n",(0,a.jsx)(n,{verse:46,children:"Now when Jonathan and the people heard these words, they gave no credit to them, nor received them because they remembered the great evil that he had done in Israel, for he had afflicted them exceedingly."}),"\n",(0,a.jsx)(n,{verse:47,children:"And their inclinations were towards Alexander, because he had been the chief promoter of peace in their regard, and him they always helped."}),"\n",(0,a.jsx)(n,{verse:48,children:"And king Alexander gathered together a great army, and moved his camp near to Demetrius."}),"\n",(0,a.jsx)(n,{verse:49,children:"And the two kings joined battle, and the army of Demetrius fled away, and Alexander pursued after him, and pressed them close."}),"\n",(0,a.jsx)(n,{verse:50,children:"And the battle was hard fought, till the sun went down: and Demetrius was slain that day."}),"\n",(0,a.jsx)(n,{verse:51,children:"And Alexander sent ambassadors to Ptolemee king of Egypt, with words to this effect, saying:"}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: Ptolemee...Surnamed Philometer."})}),"\n",(0,a.jsx)(n,{verse:52,children:"Forasmuch as I am returned into my kingdom and am set in the throne of my ancestors, and have gotten the dominion, and have overthrown Demetrius and possessed our country,"}),"\n",(0,a.jsx)(n,{verse:53,children:"And have joined battle with him, and both he and his army have been destroyed by us, and we are placed in the throne of his kingdom:"}),"\n",(0,a.jsx)(n,{verse:54,children:"Now, therefore, let us make friendship one with another: and give me now thy daughter to wife, and I will be thy son in law, and I will give both thee and her gifts worthy of thee."}),"\n",(0,a.jsx)(n,{verse:55,children:"And king Ptolomee answered, saying: Happy is the day wherein thou didst return to the land of thy fathers, and sattest in the throne of their kingdom."}),"\n",(0,a.jsx)(n,{verse:56,children:"And now I will do to thee as thou hast written but meet me at Ptolemais, that we may see one another, and I may give her to thee as thou hast said."}),"\n",(0,a.jsx)(n,{verse:57,children:"So Ptolemee went out of Egypt, with Cleopatra his daughter, and he came to Ptolemais, in the hundred and sixty-second year."}),"\n",(0,a.jsx)(n,{verse:58,children:"And king Alexander met him, and he gave him his daughter, Cleopatra: and he celebrated her marriage at Ptolemais with great glory, after the manner of kings."}),"\n",(0,a.jsx)(n,{verse:59,children:"And king Alexander wrote to Jonathan, that he should come and meet him."}),"\n",(0,a.jsx)(n,{verse:60,children:"And he went honourably to Ptolemais, and he met there the two kings, and he gave them much silver, and gold, and presents: and he found favour in their sight."}),"\n",(0,a.jsx)(n,{verse:61,children:"And some pestilent men of Israel, men of a wicked life, assembled themselves against him, to accuse him: and the king gave no heed to them."}),"\n",(0,a.jsx)(n,{verse:62,children:"And he commanded that Jonathan's garments should be taken off, and that he should be clothed with purple: and they did so. And the king made him sit by himself."}),"\n",(0,a.jsx)(n,{verse:63,children:"And he said to his princes: Go out with him into the midst of the city, and make proclamation, that no man complain against him of any matter, and that no man trouble him for any manner of cause."}),"\n",(0,a.jsx)(n,{verse:64,children:"So when his accusers saw his glory proclaimed, and him clothed with purple, they all fled away."}),"\n",(0,a.jsx)(n,{verse:65,children:"And the king magnified him, and enrolled him amongst his chief friends, and made him governor, and partaker of his dominion."}),"\n",(0,a.jsx)(n,{verse:66,children:"And Jonathan returned into Jerusalem with peace and joy."}),"\n",(0,a.jsx)(n,{verse:67,children:"In the year one hundred and sixty-five, Demetrius, the son of Demetrius, came from Crete into the land of his fathers."}),"\n",(0,a.jsx)(n,{verse:68,children:"And king Alexander heard of it, and was much troubled, and returned to Antioch."}),"\n",(0,a.jsx)(n,{verse:69,children:"And king Demetrius made Apollonius his general, who was governor of Celesyria: and he gathered together a great army, and came to Jamnia: and he sent to Jonathan, the high priest,"}),"\n",(0,a.jsx)(n,{verse:70,children:"Saying: Thou alone standest against us, and I am laughed at and reproached, because thou shewest thy power against us in the mountains."}),"\n",(0,a.jsx)(n,{verse:71,children:"Now, therefore, if thou trustest in thy forces, come down to us into the plain, and there let us try one another: for with me is the strength of war."}),"\n",(0,a.jsx)(n,{verse:72,children:"Ask, and learn who I am, and the rest that help me, who also say that your foot cannot stand before our face, for thy fathers have twice been put to flight in their own land:"}),"\n",(0,a.jsx)(n,{verse:73,children:"And now how wilt thou be able to abide the horsemen, and so great an army in the plain, where there is no stone, nor rock, nor place to flee to?"}),"\n",(0,a.jsx)(n,{verse:74,children:"Now when Jonathan heard the words of Apollonius, he was moved in his mind: and he chose ten thousand men, and went out of Jerusalem, and Simon, his brother, met him to help him."}),"\n",(0,a.jsx)(n,{verse:75,children:"And they pitched their tents near Joppe, but they shut him out of the city: because a garrison of Apollonius was in Joppe, and he laid siege to it."}),"\n",(0,a.jsx)(n,{verse:76,children:"And they that were in the city being affrighted, opened the gates to him: so Jonathan took Joppe."}),"\n",(0,a.jsx)(n,{verse:77,children:"And Apollonius heard of it, and he took three thousand horsemen, and a great army."}),"\n",(0,a.jsx)(n,{verse:78,children:"And he went to Azotus, as one that was making a journey, and immediately he went forth into the plain: because he had a great number of horsemen, and he trusted in them. And Jonathan followed after him to Azotus, and they joined battle."}),"\n",(0,a.jsx)(n,{verse:79,children:"And Apollonius left privately in the camp a thousand horsemen behind them."}),"\n",(0,a.jsx)(n,{verse:80,children:"And Jonathan knew that there was an ambush behind him, and they surrounded his army, and cast darts at the people from morning till evening."}),"\n",(0,a.jsx)(n,{verse:81,children:"But the people stood still, as Jonathan had commanded them: and so their horses were fatigued."}),"\n",(0,a.jsx)(n,{verse:82,children:"Then Simon drew forth his army, and attacked the legion: for the horsemen were wearied: and they were discomfited by him, and fled."}),"\n",(0,a.jsx)(n,{verse:83,children:"And they that were scattered about the plain fled into Azotus, and went into Bethdagon, their idol's temple, there to save themselves."}),"\n",(0,a.jsx)(n,{verse:84,children:"But Jonathan set fire to Azotus, and the cities that were round about it, and took the spoils of them and the temple of Dagon: and all them that were fled into it, he burnt with fire."}),"\n",(0,a.jsx)(n,{verse:85,children:"So they that were slain by the sword, with them that were burnt, were almost eight thousand men."}),"\n",(0,a.jsx)(n,{verse:86,children:"And Jonathan, removed his army from thence and camped against Ascalon: and they went out of the city to meet him with great honour."}),"\n",(0,a.jsx)(n,{verse:87,children:"And Jonathan returned into Jerusalem with his people, having many spoils."}),"\n",(0,a.jsx)(n,{verse:88,children:"And it came to pass, when Alexander, the king heard these words, that he honoured Jonathan yet more."}),"\n",(0,a.jsx)(n,{verse:89,children:"And he sent him a buckle of gold, as the custom is, to be given to such as are of the royal blood. And he gave him Accaron, and all the borders thereof, in possession."})]})}function m(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>s});var a=n(14041);const h={},r=a.createContext(h);function o(e){const t=a.useContext(r);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:o(e.components),a.createElement(r.Provider,{value:t},e.children)}}}]);